def chain_follower(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict[chain[0]].append(chain[1])

    stack = [chain[0]]
    result = []

    while stack:
        current = stack.pop()
        result.append(current)

        for next_item in chain_dict.get(current, []):
            stack.append(next_item)

    return ','.join(result)
